import { hash } from "bcrypt"
import { compare } from "bcryptjs"
//import { verify } from "jsonwebtoken"
//import {hash} from "argon2"

export const createhash=async(password)=>{
    //10 is round ,salt is generated by yourself
    //bcrypt
    const generatedhash=await hash(password,10)
    //argon2
    // const generatedhash=await hash(password,{
        //option take memorycost to slow process defult is 65536=64 kilo byte
       // memoryCost:1024*1024 //1MB  what process take of memory
    // })

    return generatedhash
}
//bycrpt 
export const comparehash=async(password,hashedpassword)=>{
   const ismatch=await compare(password,hashedpassword)

   //argon2
    //const ismatch=await verify(hashedpassword,password)
    //postional argment arrange parameter important 
    return ismatch
}
